        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0:
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

    # Now, fill 0s that are reachable but NOT 4-way adjacent to any Target
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) in visited:
                # Check if it is 4-way adjacent to a target
                is_adjacent = False
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == target:
                        is_adjacent = True
                        break
                if not is_adjacent:
                    grid[r][c] = target

